function nextTick(grid: number[][]): void {
  const m = grid.length, n = grid[0].length;
  const old = grid.map(row => [...row]);
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++) {
      let live = 0;
      for (let x = i - 1; x <= i + 1; x++)
        for (let y = j - 1; y <= j + 1; y++)
          if ((x !== i || y !== j) && x >= 0 && y >= 0 && x < m && y < n) live += old[x][y];
      grid[i][j] = live === 3 || (old[i][j] === 1 && live === 2) ? 1 : 0;
    }
}

