function nextTick(grid: number[][]): void {
  const m = grid.length, n = grid[0].length;
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++) {
      let live = 0;
      for (let x = Math.max(0, i - 1); x <= Math.min(m - 1, i + 1); x++)
        for (let y = Math.max(0, j - 1); y <= Math.min(n - 1, j + 1); y++)
          if (x !== i || y !== j) live += grid[x][y] & 1;
      if (live === 3 || ((grid[i][j] & 1) === 1 && live === 2)) grid[i][j] |= 2;
    }
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++) grid[i][j] >>= 1;
}

